import { requireUser } from "@/lib/auth";
import { listHostingAccounts } from "@/lib/actions-hosting";
import { HostingClient } from "@/components/customer/HostingClient";
import { PageHeader } from "@/components/ui/primitives";
import { DeployButton } from "@/components/customer/DeployButton";

export const dynamic = "force-dynamic";

// Manage-existing view only. The order/checkout wizard now lives solely on
// /dashboard/deploy?product=hosting (the unified Deploy hub) — a single source of
// truth for the money-audited HostingDeployWizard. This page lists + manages the
// customer's existing accounts and links to the hub to deploy new sites.
//
// Redesigned 2026-08-29: swapped the old big decorative <PortalHero> banner for a
// plain <PageHeader> row (title + subtitle left, single CTA right) to match the
// approved mockup's denser, table-style overview — the account cards below were
// replaced by <HostingClient>'s summary stat card + plan table.
export default async function HostingPage() {
  await requireUser();
  const accounts = await listHostingAccounts();
  return (
    <>
      <PageHeader title="Shared Hosting" sub="Manage your sites, databases, email, and files — or deploy a new site from the hub.">
        <DeployButton href="/dashboard/deploy?product=hosting">Deploy new hosting</DeployButton>
      </PageHeader>
      <HostingClient accounts={accounts} />
    </>
  );
}
