import { notFound } from "next/navigation";
import { getHostingAccount } from "@/lib/actions-hosting";
import { db } from "@/lib/db";
import { decryptSecret } from "@/lib/crypto-box";
import { hostingProvisioningStep } from "@/lib/provisioning-step";
import { StatusDot, Badge } from "@/components/ui/primitives";
import { AutoRefresh } from "@/components/AutoRefresh";
import { ProvisioningOverlay } from "@/components/customer/ProvisioningOverlay";
import { HostingTabs } from "@/components/customer/hosting/HostingTabs";

export const dynamic = "force-dynamic";

export default async function HostingAccountPage({
  params,
  searchParams,
}: {
  params: Promise<{ id: string }>;
  searchParams: Promise<{ tab?: string; path?: string; purchase?: string }>;
}) {
  const [{ id }, { tab, path, purchase }] = await Promise.all([params, searchParams]);

  // getHostingAccount enforces owner-or-admin (throws) and returns null if missing.
  let account: Awaited<ReturnType<typeof getHostingAccount>> = null;
  try {
    account = await getHostingAccount(id);
  } catch {
    notFound();
  }
  if (!account) notFound();

  const transitional = account.status === "PENDING" || account.status === "PROVISIONING";

  // Ownership/admin access was already established by getHostingAccount above —
  // this second, narrower lookup just pulls the extra raw fields the overlay
  // needs (the encrypted SFTP credential, the node's address) that the public
  // HostingAccountView doesn't carry. Real progress label: see
  // lib/provisioning-step.ts — while PENDING/PROVISIONING it's the worker's own
  // per-command-group label; once ACTIVE it's whichever content task (most
  // commonly a WordPress install queued at order time) is still running.
  const [raw, stepLabel] = await Promise.all([
    db.hostingAccount.findUnique({
      where: { id: account.id },
      select: { sftpPasswordEnc: true, node: { select: { publicIp: true, hostnameFqdn: true } } },
    }),
    hostingProvisioningStep(account.id),
  ]);
  const sftpPassword = raw?.sftpPasswordEnc ? decryptSecret(raw.sftpPasswordEnc) : null;
  const sftpHost = raw?.node?.hostnameFqdn || raw?.node?.publicIp || null;
  // True while a real follow-on step (e.g. that WordPress install) is still
  // running even though the account itself already flipped ACTIVE — see
  // ProvisioningOverlay's `liveStepActive` prop doc for why this is safe against
  // hijacking the screen for a later, casual install.
  const installStepActive = account.status === "ACTIVE" && stepLabel !== null;

  const overlay = (
    <ProvisioningOverlay
      serverId={account.id}
      status={account.status}
      transitional={transitional}
      justPaid={purchase === "1"}
      provisionError={account.error}
      productLabel="hosting account"
      hostname={account.primaryDomain}
      // Shared Hosting has no VPS-style "connect" address — the closest analogue
      // is the SFTP login, so that's what's shown here; the live site URL is a
      // separate `extraInfo` row below rather than overloading this field.
      connectAddress={sftpHost ? `sftp://${account.username}@${sftpHost}` : null}
      planName={account.planName}
      osName={null}
      rootPassword={sftpPassword}
      rootPasswordLabel="SFTP password"
      extraInfo={[
        { label: "SFTP username", value: account.username },
        { label: "Website", value: `https://${account.primaryDomain}/`, href: `https://${account.primaryDomain}/` },
      ]}
      readyStatus="ACTIVE"
      liveStep={stepLabel}
      liveStepActive={installStepActive}
      dashboardHref={`/dashboard/hosting/${account.id}`}
    />
  );

  return (
    <div>
      {overlay}
      {(transitional || installStepActive) && <AutoRefresh />}

      <div className="mb-6">
        <div className="flex flex-wrap items-center gap-3">
          <h1 className="page-title">{account.primaryDomain}</h1>
          <StatusDot status={account.status} />
          {account.sslActive && <Badge tone="green">HTTPS</Badge>}
        </div>
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <Badge tone="slate">{account.planName}</Badge>
          <Badge tone="slate">PHP {account.phpVersion}</Badge>
          <a href="/dashboard/hosting" className="text-xs text-slate-500 hover:text-slate-300 hover:underline">← All hosting</a>
        </div>
      </div>

      {transitional && (
        <div className="card mb-6 border-amber-500/30 text-sm text-amber-300">
          Your account is being set up — this usually takes under a minute. This page refreshes automatically.
        </div>
      )}

      <HostingTabs account={account} initialTab={tab} initialPath={path} />
    </div>
  );
}

/**
 * Shared-hosting account provisioner (Phase 1).
 *
 * ┌────────────────────────────────────────────────────────────────────────┐
 * │ SAFETY POSTURE — READ BEFORE ENABLING                                    │
 * │                                                                          │
 * │ This provisions UNTRUSTED customers side-by-side on ONE box. The         │
 * │ isolation shell (jailed user + per-user PHP-FPM pool + open_basedir +    │
 * │ disk quota + scoped DB + chrooted SFTP) is the standard Hestia/cPanel    │
 * │ model, but multi-tenant isolation is the one place a subtle gap is a     │
 * │ CROSS-CUSTOMER BREACH. So the whole provisioner is INERT unless          │
 * │ `ENABLE_SHARED_HOSTING=1` AND not SANDBOX. Do NOT flip that flag in      │
 * │ production until this has been (1) reviewed as a security change,        │
 * │ (2) validated end-to-end on a dedicated STAGING shared node,             │
 * │ (3) paired with fail2ban + ModSecurity + a malware scanner.             │
 * │                                                                          │
 * │ The sshd change (SFTP chroot) is `sshd -t`-validated BEFORE any reload,  │
 * │ so a bad config can never lock the box out — but it still deserves the   │
 * │ staging pass.                                                            │
 * └────────────────────────────────────────────────────────────────────────┘
 *
 * Everything a shell touches is validated through the tested pure helpers in
 * lib/hosting.ts BEFORE interpolation.
 */

import { Client } from "ssh2";
import { randomBytes } from "node:crypto";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { promises as dns } from "node:dns";
import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { decryptSecret, encryptSecret } from "../lib/crypto-box";
import {
  isValidUnixUsername,
  isValidHostingDomain,
  isValidSubdomainLabel,
  isValidCronSchedule,
  isValidCronCommand,
  subdomainPaths,
  addonDomainPaths,
  planLimits,
  diskQuotaBlocks,
  diskQuotaInodes,
  accountPaths,
  accountFsPlan,
  fpmPoolConfig,
  buildScopedGrantSql,
  buildDbMgrGrantSql,
  dbMgrUserFor,
  selfSignedCertDir,
  isValidDbToolToken,
  normalizeClaimHostname,
  hostingParkingPage,
  isFreeSubdomain,
  hostingWildcardEnabled,
  wildcardCertLiveDir,
  wildcardCoversHost,
  HOSTING_SUBDOMAIN_BASE,
} from "../lib/hosting";

/** Pinned Adminer single-file build dropped into an account webroot for the DB
 *  manager. Pinned (not "latest") like the one-click app recipes so the artifact
 *  is deterministic. */
const ADMINER_URL = "https://github.com/vrana/adminer/releases/download/v4.8.1/adminer-4.8.1.php";

/** Shell-escape the raw SQL from buildScopedGrantSql for embedding in a
 *  double-quoted `mysql -e "..."`. Identifiers/passwords are already validated
 *  to safe charsets; only the SQL's own backticks need escaping so the shell
 *  doesn't treat them as command substitution. */
function sqlForMysqlExec(sql: string): string {
  return sql.replace(/`/g, "\\`");
}

const ENABLED = process.env.ENABLE_SHARED_HOSTING === "1";
const CONNECT_TIMEOUT_MS = 20_000;
const STEP_TIMEOUT_MS = 60_000;
/** Node hardening runs the whole onboard script (apt installs — ModSecurity,
 *  ClamAV — take minutes), so it gets a much longer ceiling than a single step. */
const HARDEN_TIMEOUT_MS = 15 * 60_000;
/** Keep the TAIL of the onboard output as the stored log (the end carries the
 *  final status + any failure), capped so a chatty run can't bloat the row. */
const HARDEN_LOG_MAX = 8000;

/** Alphanumeric password (shell/SQL-safe: no quoting hazards). */
function strongPassword(len = 22): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = randomBytes(len);
  let out = "";
  for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length];
  return out;
}

async function connectNode(node: { sshHost: string; sshPort: number; rootPasswordEnc: string | null }): Promise<Client> {
  const password = node.rootPasswordEnc ? decryptSecret(node.rootPasswordEnc) : "";
  if (!password) throw new Error("Hosting node has no root credential on record.");
  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("SSH connect timed out")); }, CONNECT_TIMEOUT_MS);
    conn
      .on("ready", () => { clearTimeout(timer); resolve(); })
      .on("error", (e) => { clearTimeout(timer); reject(e); })
      .connect({ host: node.sshHost, port: node.sshPort, username: "root", password, readyTimeout: CONNECT_TIMEOUT_MS });
  });
  return conn;
}

function exec(conn: Client, command: string, timeoutMs = STEP_TIMEOUT_MS): Promise<{ code: number; out: string }> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("command timed out")), timeoutMs);
    conn.exec(command, (err, stream) => {
      if (err) { clearTimeout(timer); return reject(err); }
      let out = "";
      stream
        .on("close", (code: number) => { clearTimeout(timer); resolve({ code: code ?? 0, out }); })
        .on("data", (d: Buffer) => { out += d.toString(); })
        .stderr.on("data", (d: Buffer) => { out += d.toString(); });
    });
  });
}

"use client";

import { useEffect, useState, type ReactNode } from "react";
import {
  getHostingAccount,
  revealHostingSftpPassword,
  recheckHostingHealth,
  listHostingSubdomains,
  listHostingAddonDomains,
  listHostingDatabases,
  cancelHostingAccount,
  type HostingAccountView,
} from "@/lib/actions-hosting";
import { Badge, StatusDot } from "@/components/ui/primitives";
import { QuotaTile, GettingStarted, TaskFeed, type TaskView } from "./shared";
import { AppCredentials } from "./AppCredentials";
import { FileManager } from "./FileManager";
import { Backups } from "./Backups";
import { AppInstaller } from "./AppInstaller";
import { DatabasesPanel } from "./DatabasesPanel";
import { PhpSwitcher } from "./PhpSwitcher";
import { SubdomainsPanel } from "./SubdomainsPanel";
import { AddonDomainsPanel } from "./AddonDomainsPanel";
import { WebsitesPanel } from "./WebsitesPanel";
import { CronPanel } from "./CronPanel";
import { EmailTab } from "./EmailTab";
import { PlanUpgrade } from "./PlanUpgrade";

const TABS = ["Overview", "Websites", "Files", "Databases", "Domains", "Email", "Apps", "Cron", "Backups", "Settings"] as const;

export function HostingTabs({ account, initialTab, initialPath }: { account: HostingAccountView; initialTab?: string; initialPath?: string }) {
  const keys = TABS.map((t) => t.toLowerCase());
  const [tab, setTab] = useState<string>(
    initialTab && keys.includes(initialTab.toLowerCase()) ? initialTab.toLowerCase() : "overview",
  );

  const active = account.status === "ACTIVE";

  const panels: Record<string, ReactNode> = {
    overview: <Overview account={account} />,
    websites: active ? <WebsitesPanel accountId={account.id} /> : <NotReady />,
    files: active ? <FileManager accountId={account.id} initialPath={initialPath} /> : <NotReady />,
    databases: active ? <DatabasesPanel accountId={account.id} username={account.username} maxDatabases={account.maxDatabases} /> : <NotReady />,
    domains: active ? <DomainsTab account={account} /> : <NotReady />,
    email: active ? <EmailTab account={account} /> : <NotReady />,
    apps: active ? <AppsTab account={account} /> : <NotReady />,
    cron: active ? <CronPanel accountId={account.id} username={account.username} /> : <NotReady />,
    backups: active ? <Backups accountId={account.id} /> : <NotReady />,
    settings: <SettingsTab account={account} />,
  };

  return (
    <div>
      <div className="mb-6 flex gap-1 overflow-x-auto rounded-2xl border border-white/[0.06] bg-navy-900/70 p-1 backdrop-blur-md">
        {TABS.map((t) => {
          const k = t.toLowerCase();
          const isActive = tab === k;
          return (
            <button
              key={k}
              type="button"
              onClick={() => { setTab(k); window.history.replaceState(null, "", `?tab=${k}`); }}
              className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium transition-colors ${
                isActive
                  ? "bg-gradient-to-r from-accent-blue/90 to-brand-500/90 text-white shadow-[0_4px_16px_-6px_rgb(111_71_245_/_0.6)]"
                  : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              {t}
            </button>
          );
        })}
      </div>
      <div className="animate-fade-up">{panels[tab]}</div>
    </div>
  );
}

function NotReady() {
  return (
    <div className="card py-12 text-center">
      <h2 className="font-semibold">Still being set up</h2>
      <p className="mx-auto mt-2 max-w-md text-sm text-slate-400">
        This account is provisioning — it usually takes under a minute. This section lights up once it’s active.
      </p>
    </div>
  );
}

/* ------------------------------------------------------------- Overview --- */

function Overview({ account }: { account: HostingAccountView }) {
  const [a, setA] = useState(account);
  const [sftpPw, setSftpPw] = useState<string | null>(null);
  const [tasks, setTasks] = useState<TaskView[]>([]);
  const [counts, setCounts] = useState<{ subs: number; addons: number; dbs: number } | null>(null);
  const [recheckBusy, setRecheckBusy] = useState(false);

  const active = a.status === "ACTIVE";
  const diskGB = Math.round(a.diskQuotaMB / 1024);

  // "Check now / Go live": flag an immediate recheck, then poll the account for
  // ~45s so the stepper reflects the fast-lane result (every ~30s worker tick).
  async function recheck() {
    setRecheckBusy(true);
    const r = await recheckHostingHealth(a.id);
    if (r.error) { alert(r.error); setRecheckBusy(false); return; }
    let tries = 0;
    const poll = setInterval(() => {
      tries++;
      getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {});
      if (tries >= 9) { clearInterval(poll); setRecheckBusy(false); }
    }, 5000);
  }

  // Live-refresh the account (SSL status) until HTTPS is active, so the DNS→HTTPS
  // stepper advances on its own.
  useEffect(() => {
    if (!active || a.sslActive) return;
    const t = setInterval(() => { getHostingAccount(a.id).then((fresh) => { if (fresh) setA(fresh); }).catch(() => {}); }, 15000);
    return () => clearInterval(t);
  }, [a.id, active, a.sslActive]);

  // Counts for the usage meters (extra sites + databases).
  useEffect(() => {
    if (!active) return;
    Promise.all([
      listHostingSubdomains(a.id).catch(() => []),
      listHostingAddonDomains(a.id).catch(() => []),
      listHostingDatabases(a.id).catch(() => []),
    ]).then(([subs, addons, dbs]) => setCounts({
      subs: subs.filter((s) => s.status !== "DELETING").length,
      addons: addons.filter((d) => d.status !== "DELETING").length,
      dbs: dbs.length,
    }));
  }, [a.id, active]);

  async function reveal() {
    const res = await revealHostingSftpPassword(a.id);
    if (res.password) setSftpPw(res.password); else if (res.error) alert(res.error);
  }

  const extraSites = counts ? counts.subs + counts.addons : 0;

  return (
    <div className="space-y-6">
      {a.status === "FAILED" && (
        <div className="card border-red-500/30 text-sm text-red-300">Setup failed{a.error ? `: ${a.error}` : ""}. Contact support or retry from the hosting list.</div>
      )}
      {(a.status === "PENDING" || a.status === "PROVISIONING") && (
        <div className="card border-amber-500/30 text-sm text-amber-200">We’re setting up your account — this usually takes under a minute.</div>
      )}

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Summary */}
        <div className="card">
          <h2 className="mb-4 font-semibold">Overview</h2>
          <dl className="space-y-2.5 text-sm">
            <div className="flex items-center justify-between"><dt className="text-slate-400">Status</dt><dd><StatusDot status={a.status} /></dd></div>
            <div className="flex items-center justify-between"><dt className="text-slate-400">Plan</dt><dd>{a.planName}</dd></div>
            <div className="flex items-center justify-between"><dt className="text-slate-400">PHP version</dt><dd className="font-mono text-xs">{a.phpVersion}</dd></div>
            <div className="flex items-center justify-between">
              <dt className="text-slate-400">Website</dt>
              <dd>
                <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="text-brand-300 hover:underline">{a.primaryDomain}</a>
                {a.sslActive && <Badge tone="green">HTTPS</Badge>}
              </dd>
            </div>
          </dl>
        </div>

        {/* Free subdomain → already live (wildcard DNS); real domain → point-DNS flow */}
        <div className="card">
          <div className="mb-4 flex items-center justify-between gap-2">
            <h2 className="font-semibold">{a.isFreeSubdomain ? "Your website" : "Point your domain"}</h2>
            {active && (
              <button
                type="button"
                className="btn-secondary px-2.5 py-1 text-xs"
                disabled={recheckBusy}
                onClick={recheck}
              >
                {recheckBusy ? "Checking…" : a.sslActive ? "Check now" : a.isFreeSubdomain ? "Refresh" : "Go live"}
              </button>
            )}
          </div>
          {a.isFreeSubdomain ? (
            <p className="text-sm text-slate-400">
              Your free subdomain{" "}
              <a href={a.sslActive ? `https://${a.primaryDomain}` : `http://${a.primaryDomain}`} target="_blank" rel="noreferrer" className="font-mono text-brand-200 hover:underline">{a.primaryDomain}</a>{" "}
              is set up for you automatically — nothing to configure. It goes live the moment provisioning finishes, and a
              trusted HTTPS certificate is issued right after. Want a custom domain? Add one anytime from the{" "}
              <span className="text-slate-300">Domains</span> tab.
            </p>
          ) : (
            <p className="text-sm text-slate-400">
              Create an <span className="font-mono text-slate-200">A</span> record for{" "}
              <span className="font-mono text-slate-200">{a.primaryDomain}</span> →{" "}
              <span className="font-mono text-brand-200">{a.pointToA}</span>
              {a.pointToCname && (<>{" "}(or a <span className="font-mono text-slate-200">CNAME</span> to <span className="font-mono text-slate-200">{a.pointToCname}</span>)</>)}.
            </p>
          )}
          <DnsStepper account={a} />
        </div>
      </div>

      {/* Usage meters */}
      {active && (
        <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
          <QuotaTile
            label="Storage"
            primary={a.diskUsedMB != null ? `${(a.diskUsedMB / 1024).toFixed(a.diskUsedMB < 1024 ? 2 : 1)} of ${diskGB} GB` : `${diskGB} GB SSD`}
            bar={a.diskUsedMB != null ? { used: a.diskUsedMB, total: a.diskQuotaMB } : undefined}
            note={a.diskUsedMB == null ? "Updates automatically once your site is live" : undefined}
          />
          <QuotaTile
            label="Inodes (files)"
            primary={a.inodesUsed != null ? a.inodesUsed.toLocaleString() : "—"}
            note={a.inodesUsed == null ? "Measured once your site is live" : "Total files & folders"}
          />
          <QuotaTile
            label="Extra sites"
            primary={`${extraSites} of ${a.maxSites}`}
            bar={{ used: extraSites, total: a.maxSites }}
            note="Subdomains + addon domains (primary is always live)"
          />
          <QuotaTile
            label="Databases"
            primary={a.maxDatabases > 0 ? `${counts?.dbs ?? 0} of ${a.maxDatabases}` : "Not on this plan"}
            bar={a.maxDatabases > 0 ? { used: counts?.dbs ?? 0, total: a.maxDatabases } : undefined}
          />
        </div>
      )}

      {/* SFTP access */}
      {active && (
        <div className="flex flex-wrap items-center gap-2 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-sm">
          <span className="font-medium text-slate-300">SFTP</span>
          <span className="text-slate-400"><span className="font-mono text-slate-200">{a.username}</span>@{a.pointToA}</span>
          {sftpPw ? (
            <span className="font-mono text-brand-200">{sftpPw}</span>
          ) : (
            <button className="text-xs text-brand-300 hover:underline" onClick={reveal}>show password</button>
          )}
        </div>
      )}

      {/* Getting started + task progress */}
      {active && <AppCredentials accountId={a.id} />}
      {active && <GettingStarted accountId={a.id} freeSubdomain={a.isFreeSubdomain} primaryDomain={a.primaryDomain} />}
      <TaskFeed accountId={a.id} active={active} onTasks={setTasks} />
      {/* tasks kept for the feed; referenced to avoid an unused-setter lint */}
      <span className="hidden">{tasks.length}</span>
    </div>
  );
}

/**
 * DNS→HTTPS stepper driven by the REAL serve-verification the worker records
 * (serveHttpOk / serveHttpsOk / sslActive), so it can never claim "live" while
 * HTTPS actually refuses. Three overall states, per the account's measured health:
 *   • verified — a trusted cert is live (sslActive) and 443 answers → "HTTPS live ✓"
 *   • issuing  — the site answers (self-signed 443 or HTTP) but no trusted cert yet
 *   • dns      — nothing answers for the domain yet (DNS not pointed at us)
 */
function DnsStepper({ account }: { account: HostingAccountView }) {
  const checked = account.healthCheckedAt != null || account.serveHttpOk != null;
  const serving = account.serveHttpOk === true || account.serveHttpsOk === true;
  const verified = account.sslActive && account.serveHttpsOk !== false;
  const state: "verified" | "issuing" | "dns" | "pending" =
    verified ? "verified" : serving ? "issuing" : checked ? "dns" : "pending";

  const free = account.isFreeSubdomain;
  const steps = [
    { label: free ? "DNS ready" : "Point domain", done: true, hint: free ? "Set up automatically" : "Add the A record above" },
    {
      label: "Site live",
      done: state === "issuing" || state === "verified",
      hint: state === "issuing" || state === "verified" ? "Serving traffic" : state === "dns" ? "DNS not detected yet" : "Checking…",
    },
    {
      label: "HTTPS verified",
      done: state === "verified",
      hint: state === "verified" ? "Certificate trusted" : state === "issuing" ? "Issuing certificate" : "Auto after DNS",
    },
  ];

  const headline =
    account.healthNote ??
    (state === "verified" ? "HTTPS live — verified" : state === "issuing" ? "HTTP live, HTTPS issuing" : state === "dns" ? "DNS not detected yet" : "Not checked yet");
  const headlineTone = state === "verified" ? "text-emerald-300" : state === "dns" ? "text-slate-400" : "text-amber-300";

  return (
    <div className="mt-4">
      <div className="flex items-center">
        {steps.map((s, i) => (
          <div key={s.label} className="flex flex-1 items-center last:flex-none">
            <div className="flex flex-col items-center">
              <span className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] ${s.done ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300" : "border-amber-500/40 bg-amber-500/10 text-amber-300"}`}>
                {s.done ? "✓" : i + 1}
              </span>
            </div>
            {i < steps.length - 1 && <div className={`mx-2 h-px flex-1 ${steps[i + 1].done ? "bg-emerald-500/40" : "bg-white/10"}`} />}
          </div>
        ))}
      </div>
      <div className="mt-1.5 flex items-start justify-between text-[11px]">
        {steps.map((s) => (
          <div key={s.label} className="flex-1 text-center first:text-left last:text-right">
            <p className={s.done ? "text-emerald-300" : "text-slate-400"}>{s.label}</p>
            <p className="text-slate-500">{s.hint}</p>
          </div>
        ))}
      </div>
      <p className={`mt-3 text-xs font-medium ${headlineTone}`}>
        {headline}
        {account.healthCheckedAt && (
          <span className="ml-1 font-normal text-slate-500">· checked {new Date(account.healthCheckedAt).toLocaleTimeString()}</span>
        )}
      </p>
      {state !== "verified" && (
        <p className="mt-1 text-xs text-slate-500">
          {free ? (
            <>A trusted HTTPS certificate is issued automatically once provisioning completes — this usually takes a minute. Use <span className="text-slate-300">Refresh</span> to check right away.</>
          ) : (
            <>A trusted HTTPS certificate is issued automatically once your domain resolves to us — this can take a few minutes after you set the DNS record. Use <span className="text-slate-300">Go live</span> to check right away.</>
          )}
        </p>
      )}
    </div>
  );
}

