// Shared-hosting file manager over SFTP.
//
// SECURITY: we connect AS THE JAILED ACCOUNT USER (chrooted internal-sftp), so
// the operating-system chroot is the jail — a tenant symlink can never resolve
// outside their own tree. Do NOT connect as root here: a lexical path check
// cannot stop root's SFTP following a tenant-planted symlink (audit 2026-08-01).
// The lexical checks below are defence-in-depth only.

import { Client, type SFTPWrapper } from "ssh2";
import { decryptSecret } from "./crypto-box";

export type HostingFsTarget = { sshHost: string; sshPort: number; username: string; sftpPassword: string };

/** Build the chrooted-SFTP target for an account (connects AS the jailed user, so
 *  the OS chroot is the jail — never as root, which a symlink can escape).
 *  Returns null if the account has no stored SFTP password yet. Lives in this
 *  plain module (not the "use server" actions file) because it is synchronous. */
export function fsTargetFor(a: { node: { sshHost: string; sshPort: number }; username: string; sftpPasswordEnc: string | null }): HostingFsTarget | null {
  const pw = a.sftpPasswordEnc ? decryptSecret(a.sftpPasswordEnc) : null;
  if (!pw) return null;
  return { sshHost: a.node.sshHost, sshPort: a.node.sshPort, username: a.username, sftpPassword: pw };
}
export type FsEntry = { name: string; isDir: boolean; size: number; modified: number };

const CONNECT_TIMEOUT_MS = 20_000;

/** A relative, traversal-free path inside the account chroot. Defence-in-depth:
 *  the chroot is the real boundary; this just rejects obviously-bad input. */
export function safeRel(relPath: string): string {
  const rel = String(relPath ?? "").replace(/\\/g, "/").replace(/^\/+/, "").replace(/\/+/g, "/");
  if (!rel) return "public_html";
  if (rel.includes("..") || rel.includes("\0")) throw new Error("invalid path");
  if (!/^[A-Za-z0-9._/\- ]{1,1024}$/.test(rel)) throw new Error("invalid path chars");
  return rel;
}

async function connect(t: HostingFsTarget): Promise<Client> {
  if (!/^[a-z][a-z0-9]{2,31}$/.test(t.username) || !t.sftpPassword) throw new Error("bad account credential");
  const conn = new Client();
  await new Promise<void>((resolve, reject) => {
    const timer = setTimeout(() => { try { conn.end(); } catch { /* */ } reject(new Error("connect timeout")); }, CONNECT_TIMEOUT_MS);
    conn.on("ready", () => { clearTimeout(timer); resolve(); })
      .on("error", (e) => { clearTimeout(timer); reject(e); })
      // Connect as the ACCOUNT USER — the sshd chroot confines the whole session.
      .connect({ host: t.sshHost, port: t.sshPort, username: t.username, password: t.sftpPassword, readyTimeout: CONNECT_TIMEOUT_MS });
  });
  return conn;
}

function sftpOf(conn: Client): Promise<SFTPWrapper> {
  return new Promise((resolve, reject) => conn.sftp((err, sftp) => (err ? reject(err) : resolve(sftp))));
}

async function withSftp<T>(t: HostingFsTarget, fn: (sftp: SFTPWrapper) => Promise<T>): Promise<T> {
  const conn = await connect(t);
  try {
    return await fn(await sftpOf(conn));
  } finally {
    try { conn.end(); } catch { /* */ }
  }
}

export async function fsList(t: HostingFsTarget, relPath: string): Promise<FsEntry[]> {
  const p = safeRel(relPath);
  return withSftp(t, (sftp) => new Promise<FsEntry[]>((resolve, reject) => {
    sftp.readdir(p, (err, list) => {
      if (err) return reject(err);
      resolve(
        list
          .map((e) => ({ name: e.filename, isDir: (e.attrs.mode & 0o40000) !== 0, size: e.attrs.size, modified: (e.attrs.mtime ?? 0) * 1000 }))
          .filter((e) => e.name !== "." && e.name !== "..")
          .sort((a, b) => Number(b.isDir) - Number(a.isDir) || a.name.localeCompare(b.name)),
      );
    });
  }));
}

export async function fsMkdir(t: HostingFsTarget, relPath: string): Promise<void> {
  const p = safeRel(relPath);
  await withSftp(t, (sftp) => new Promise<void>((resolve, reject) => sftp.mkdir(p, (e) => (e ? reject(e) : resolve()))));
}

export async function fsDelete(t: HostingFsTarget, relPath: string, isDir: boolean): Promise<void> {
  const p = safeRel(relPath);
  await withSftp(t, (sftp) => new Promise<void>((resolve, reject) => {
    const op = isDir ? sftp.rmdir.bind(sftp) : sftp.unlink.bind(sftp);
    op(p, (e) => (e ? reject(e) : resolve()));
  }));
}

/** Byte size of a file via SFTP stat, WITHOUT reading it — so a caller can reject
 *  an oversized download before fsReadBuffer buffers the whole thing into memory
 *  (an OOM DoS otherwise: a tenant's multi-GB file would be Buffer.concat'd whole,
 *  audit MEDIUM-3). Returns the size in bytes. */
export async function fsStatSize(t: HostingFsTarget, relPath: string): Promise<number> {
  const p = safeRel(relPath);
  return withSftp(t, (sftp) => new Promise<number>((resolve, reject) => {
    sftp.stat(p, (err, stats) => (err ? reject(err) : resolve(Number(stats.size) || 0)));
  }));
}

export async function fsReadBuffer(t: HostingFsTarget, relPath: string): Promise<Buffer> {
  const p = safeRel(relPath);
  return withSftp(t, (sftp) => new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    const stream = sftp.createReadStream(p);
    stream.on("data", (d: Buffer) => chunks.push(d));
    stream.on("end", () => resolve(Buffer.concat(chunks)));
    stream.on("error", reject);
  }));
}

export async function fsWriteBuffer(t: HostingFsTarget, relPath: string, buf: Buffer): Promise<void> {
  const p = safeRel(relPath);
  await withSftp(t, (sftp) => new Promise<void>((resolve, reject) => {
    const stream = sftp.createWriteStream(p);
    stream.on("close", () => resolve());
    stream.on("error", reject);
    stream.end(buf);
  }));
}

"use client";

import { useCallback, useEffect, useRef, useState, useTransition } from "react";
import { hostingListFiles, hostingMkdir, hostingDeleteFile, type FsEntryView } from "@/lib/actions-hosting";
import { fmtBytes } from "@/components/ui/primitives";

/**
 * In-browser file manager for a hosting account. Matches the VPS Files tab
 * (components/customer/FileManager) design — card toolbar with breadcrumbs,
 * drag-and-drop upload, a proper table listing — but keeps the hosting SFTP-jailed
 * backend (hostingListFiles / hostingMkdir / hostingDeleteFile + the
 * /api/hosting/files upload/download route). The tenant's chroot is the boundary;
 * everything here is confined to their own /home/<user> tree. The account webroot
 * (`public_html`) is the root the customer starts and stays within.
 */

const ROOT = "public_html";

function fmtWhen(ms: number): string {
  if (!ms || ms <= 0) return "—";
  const d = new Date(ms);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toISOString().slice(0, 16).replace("T", " ");
}

function parentOf(path: string): string {
  const parts = path.split("/").filter(Boolean);
  parts.pop();
  return parts.join("/") || ROOT;
}

function FolderIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#8a70fb" strokeWidth="1.6" aria-hidden>
      <path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
    </svg>
  );
}

function FileIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="1.6" aria-hidden>
      <path d="M6 3h8l4 4v14a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z" />
      <path d="M14 3v4h4" />
    </svg>
  );
}

export function FileManager({ accountId, initialPath }: { accountId: string; initialPath?: string }) {
  // Optional deep-link into a specific site's docroot (e.g. a subdomain/addon the
  // Websites panel's "Open files" points at). Falls back to the primary webroot.
  const startPath = (() => {
    const raw = String(initialPath ?? "").replace(/^\/+/, "").trim();
    return raw && /^[A-Za-z0-9._/\- ]{1,1024}$/.test(raw) ? raw : ROOT;
  })();
  const [path, setPath] = useState(startPath);
  const [entries, setEntries] = useState<FsEntryView[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [pending, start] = useTransition();

  const fileInputRef = useRef<HTMLInputElement>(null);

  const load = useCallback(
    (target: string) => {
      setLoading(true);
      setError(null);
      start(async () => {
        const res = await hostingListFiles(accountId, target);
        if (res.error) {
          setError(res.error);
        } else {
          setPath(res.path ?? target);
          setEntries(res.entries ?? []);
        }
        setLoading(false);
      });
    },
    [accountId],
  );

  useEffect(() => {
    load(startPath);
  }, [load, startPath]);

  const refresh = useCallback(() => load(path), [load, path]);

  function flash(msg: string) {
    setNotice(msg);
    setTimeout(() => setNotice(null), 3000);
  }

  // ---- Breadcrumbs (rooted at public_html) ----
  const crumbs = (() => {
    const parts = path.split("/").filter(Boolean);
    const out: { label: string; path: string }[] = [];
    let acc = "";
    for (const p of parts) {
      acc = acc ? `${acc}/${p}` : p;
      out.push({ label: p, path: acc });
    }
    if (out.length === 0) out.push({ label: ROOT, path: ROOT });
    return out;
  })();

  // ---- Uploads ----
  const uploadFiles = useCallback(
    async (files: FileList | File[]) => {
      const list = Array.from(files);
      if (list.length === 0) return;
      setUploading(true);
      setError(null);
      let failed = 0;
      for (const file of list) {
        try {
          const fd = new FormData();
          fd.set("file", file);
          const res = await fetch(`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(path)}`, { method: "POST", body: fd });
          if (!res.ok) {
            failed++;
            const body = await res.json().catch(() => ({}));
            setError(body.error || `Upload failed for ${file.name}.`);
          }
        } catch {
          failed++;
          setError(`Upload failed for ${file.name}.`);
        }
      }
      setUploading(false);
      if (failed === 0) flash(`Uploaded ${list.length} file${list.length === 1 ? "" : "s"}.`);
      refresh();
    },
    [accountId, path, refresh],
  );

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer.files?.length) uploadFiles(e.dataTransfer.files);
  };

  // ---- Mutations ----
  function newFolder() {
    const name = window.prompt("New folder name:");
    if (!name) return;
    setError(null);
    start(async () => {
      const res = await hostingMkdir(accountId, path, name);
      if (res.error) setError(res.error);
      else { flash("Folder created."); load(path); }
    });
  }

  function remove(entry: FsEntryView) {
    const what = entry.isDir ? "folder and everything inside it" : "file";
    if (!window.confirm(`Delete this ${what}? "${entry.name}" cannot be recovered.`)) return;
    setError(null);
    start(async () => {
      const res = await hostingDeleteFile(accountId, `${path}/${entry.name}`, entry.isDir);
      if (res.error) setError(res.error);
      else { flash("Deleted."); load(path); }
    });
  }

  const busy = pending || loading;

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="card flex flex-wrap items-center justify-between gap-3">
        <div className="min-w-0 flex flex-wrap items-center gap-1 text-sm">
          {crumbs.map((c, i) => (
            <span key={c.path} className="flex items-center gap-1">
              {i > 0 && <span className="text-slate-600">/</span>}
              <button
                type="button"
                onClick={() => load(c.path)}
                className={`rounded-lg px-2 py-1 font-mono text-xs transition-colors hover:bg-white/[0.06] ${
                  i === crumbs.length - 1 ? "text-brand-300" : "text-slate-400"
                }`}
              >
                {c.label}
              </button>
            </span>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <button type="button" className="btn-secondary px-3 py-1.5 text-sm" onClick={() => fileInputRef.current?.click()} disabled={uploading}>
            {uploading ? "Uploading…" : "Upload"}
          </button>
          <button type="button" className="btn-secondary px-3 py-1.5 text-sm" onClick={newFolder} disabled={busy}>
            New folder
          </button>
          <button type="button" className="btn-ghost px-3 py-1.5 text-sm" onClick={refresh} disabled={busy} title="Refresh">
            Refresh
          </button>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            className="hidden"
            onChange={(e) => {
              if (e.target.files?.length) uploadFiles(e.target.files);
              e.target.value = "";
            }}
          />
        </div>
      </div>

      {notice && (
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 px-4 py-2 text-sm text-emerald-300">{notice}</div>
      )}
      {error && (
        <div className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm text-red-300">{error}</div>
      )}

      {/* File listing (also the drop target) */}
      <div
        className={`card p-0 transition-colors ${dragOver ? "border-brand-400/60 bg-brand-500/[0.06]" : ""}`}
        onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="flex items-center justify-between px-4 pt-4">
          <p className="section-label">Files</p>
          <p className="text-xs text-slate-500">Drag &amp; drop files here to upload</p>
        </div>

        {loading ? (
          <div className="space-y-2 p-4">
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-full" />
            <div className="skeleton h-8 w-2/3" />
          </div>
        ) : (
          <table className="table-shell mt-2">
            <thead>
              <tr>
                <th>Name</th>
                <th className="text-right">Size</th>
                <th>Modified</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {path !== ROOT && (
                <tr>
                  <td colSpan={4}>
                    <button
                      type="button"
                      className="flex items-center gap-2 text-sm text-slate-400 hover:text-white"
                      onClick={() => load(parentOf(path))}
                    >
                      <FolderIcon />
                      <span className="font-mono">..</span>
                    </button>
                  </td>
                </tr>
              )}
              {entries.map((entry) => (
                <tr key={entry.name}>
                  <td>
                    {entry.isDir ? (
                      <button
                        type="button"
                        className="flex items-center gap-2 text-left hover:text-white"
                        onClick={() => load(`${path}/${entry.name}`)}
                      >
                        <FolderIcon />
                        <span className="font-medium">{entry.name}</span>
                      </button>
                    ) : (
                      <a
                        className="flex items-center gap-2 text-left text-slate-200 hover:text-white"
                        href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${entry.name}`)}`}
                      >
                        <FileIcon />
                        <span>{entry.name}</span>
                      </a>
                    )}
                  </td>
                  <td className="text-right text-slate-400">{entry.isDir ? "—" : fmtBytes(entry.size)}</td>
                  <td className="text-slate-400">{fmtWhen(entry.modified)}</td>
                  <td>
                    <div className="flex items-center justify-end gap-1">
                      {!entry.isDir && (
                        <a
                          className="btn-ghost px-2 py-1 text-xs"
                          href={`/api/hosting/files?accountId=${accountId}&path=${encodeURIComponent(`${path}/${entry.name}`)}`}
                        >
                          Download
                        </a>
                      )}
                      <button type="button" className="btn-danger px-2 py-1 text-xs" onClick={() => remove(entry)} disabled={busy}>
                        Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {entries.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-4 py-8 text-center text-sm text-slate-500">
                    This folder is empty. Upload your site files here, or install an app.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

