// every 3 min (was 30) so a customer who points DNS mid-interval gets HTTPS in
// minutes, not up to half an hour. certbot is --keep-until-expiring, so a tighter
// cadence never re-issues an unexpired cert (no Let's Encrypt rate-limit churn).
if (Date.now() - lastHostingSslSweep > 3 * 60_000) {
  lastHostingSslSweep = Date.now();
  try {
    await hostingSslSweep();
    await hostingUsageSweep();
  } catch (e) {
    console.error("[hosting] ssl sweep error", e);
  }
}
// Serve-verification + self-heal for every ACTIVE account (~10 min). Confirms
// nginx actually answers on 80/443 and repairs a stale real-cert vhost, so a
// live customer never sees the panel claim "active" while HTTPS refuses. Also
// inert until ENABLE_SHARED_HOSTING; simulates in sandbox.
if (Date.now() - lastHostingHealthSweep > 10 * 60_000) {
  lastHostingHealthSweep = Date.now();
  try {
    await hostingHealthSweep();
  } catch (e) {
    console.error("[hosting] health sweep error", e);
  }
}
// Wildcard TLS cert for FREE SUBDOMAINS: ensure `*.<base>` (+ apex) exists and is
// current on every enabled hosting node via certbot DNS-01/Cloudflare, so free-
// subdomain sites get instant trusted HTTPS off ONE Let's Encrypt lineage instead
// of a per-subdomain cert (slow + capped at ~50/week per registered domain). Fully
// opt-in + inert: a no-op unless HOSTING_WILDCARD_SSL=1 AND CLOUDFLARE_DNS_API_TOKEN
// is set AND shared hosting is enabled (and not sandbox). ~Daily cadence; certbot's
// --keep-until-expiring keeps each tick a cheap no-op until renewal is actually due.

