model Site {
  id          String        @id @default(cuid())
  userId      String
  name        String
  slug        String // the *.nxeon subdomain label; globally unique
  websiteId   String? // the Website row it publishes into once live
  status      String        @default("DRAFT") // DRAFT | PUBLISHING | PUBLISHED | FAILED
  templateKey String? // starter template it began from
  publishedAt DateTime?
  error       String?
  createdAt   DateTime      @default(now())
  updatedAt   DateTime      @updatedAt
  pages       SitePage[]
  versions    SiteVersion[]
  assets      SiteAsset[]

  @@unique([slug])
  @@index([userId])
  @@index([status])
}

model SitePage {
  id        String   @id @default(cuid())
  siteId    String
  site      Site     @relation(fields: [siteId], references: [id], onDelete: Cascade)
  path      String // "/", "/about"
  title     String   @default("")
  seoDesc   String?
  sortOrder Int      @default(0)
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@unique([siteId, path])
  @@index([siteId])
}

/// Immutable editor-document snapshot. `isDraft` marks the working copy;
/// `publishedAt` set on the version that is live — draft + rollback for free.
model SiteVersion {
  id          String    @id @default(cuid())
  siteId      String
  site        Site      @relation(fields: [siteId], references: [id], onDelete: Cascade)
  document    Json // editor doc (html+css / component JSON) keyed by page path
  label       String?
  isDraft     Boolean   @default(true)
  publishedAt DateTime?
  createdAt   DateTime  @default(now())

  @@index([siteId, createdAt])
}

model SiteAsset {
  id        String   @id @default(cuid())
  siteId    String
  site      Site     @relation(fields: [siteId], references: [id], onDelete: Cascade)
  path      String // storage path / URL under the media root
  filename  String
  mimeType  String
  sizeBytes BigInt
  createdAt DateTime @default(now())

  @@index([siteId])
}

// ============================================================================
// Observability — additive tables behind the status/health/error features.
// ============================================================================

/// Persisted application errors — the DB sink behind lib/log.ts (previously
/// stderr + optional webhook only). Deduplicated by fingerprint: an identical
/// repeated error bumps count/lastSeen instead of spamming rows.
model ErrorLog {
==== VOLUME ====
model Volume {
  id         String    @id @default(cuid())
  userId     String
  user       User      @relation(fields: [userId], references: [id], onDelete: Cascade)
  serverId   String?
  server     Server?   @relation(fields: [serverId], references: [id], onDelete: SetNull)
  name       String
  sizeGB     Int
  priceCents Int
  status     String    @default("PENDING") // PENDING | ATTACHED | DETACHED | DELETING
  diskName   String? // proxmox disk slot (e.g. scsi1)
  // Set once the volume has actually been formatted and mounted on the server, or
  // adopted as Docker storage. A detach while this is true silently pulls the
  // filesystem out from under running services — which is exactly what the UI's
  // "Data is preserved." reassurance promised could not happen. Safe-detach
  // consults this; nothing may detach a depended-on volume without an explicit,
  // informed override.
  inUse      Boolean   @default(false)
  mountPath  String? // where it is mounted on the guest, when known (e.g. /mnt/vol-1)
  fsType     String? // filesystem we created on it (e.g. ext4); null = never formatted
  createdAt  DateTime  @default(now())
  expiresAt  DateTime?
}

/**
 * One row per Checkout session we have taken responsibility for fulfilling.
 * Fulfilment used to be gated on `creditCheckoutSession()`'s return value, which
 * is true ONLY for the caller that won the race to insert the wallet credit. The
 * webhook and the success-redirect both call it, so whichever lost saw `false`
 * and silently skipped provisioning — and the redirect is the one that carried
 * the fulfilment logic. Two live failure modes: the webhook wins the race, or the
 * customer simply closes the tab before `success_url` resolves (100% reproducible).
 * Either way: card charged, wallet credited, no server, no error, no alert.
 * The claim is made by INSERTING this row — the UNIQUE index decides the single
 * winner, so both callers can attempt fulfilment and exactly one proceeds. Status
 * is kept so a failure after claiming is visible for reconciliation instead of
 * silently blocking a retry.
 */
model FulfilledSession {
  id              String   @id @default(cuid())
  stripeSessionId String   @unique
  kind            String // "order" | "resize" | "diskExpand" | "topup"
==== NXCLOUD ====
enum NxCloudStatus {
  PENDING // ordered, awaiting the provisioner
  PROVISIONING // VM cloning / Nextcloud installing
  ACTIVE
  SUSPENDED // non-payment or admin (mirrors the backing Server)
  FAILED
  DELETING
}

/// A managed Nextcloud plan (a storage-led product tier). Carries the pricing +
/// marketing surface; the VM sizing the provisioner actually reads comes from the
/// linked backing `serverPlan` (kept `active = false` so it never appears in the
/// VPS storefront). The two are seeded in lockstep so display === charged.
model NxCloudPlan {
  id           String            @id @default(cuid())
  slug         String            @unique
  name         String
  priceCents   Int
  storageGB    Int // = VM disk (matches serverPlan.diskGB)
  ramMB        Int // display mirror of serverPlan.ramMB
  vcpu         Int // display mirror of serverPlan.cpuCores
  bandwidthTB  Float             @default(1)
  collabora    Boolean           @default(false) // office suite enabled on this tier
  talk         Boolean           @default(false) // video/chat enabled on this tier
  featured     Boolean           @default(false)
  tagline      String            @default("")
  active       Boolean           @default(true)
  sortOrder    Int               @default(0)
  createdAt    DateTime          @default(now())
  // The VPS Plan the backing VM is cloned/sized from. Reusing Plan is what lets
  // the whole Server lifecycle + the audited billing sweep work unchanged.
  serverPlanId String
  serverPlan   Plan              @relation(fields: [serverPlanId], references: [id])
  instances    NxCloudInstance[]
}

/// One customer's managed Nextcloud instance — the unit of isolation, access and
/// display. Billing rides the backing `server`; this row is the product wrapper.
model NxCloudInstance {
  id             String        @id @default(cuid())
  userId         String
  user           User          @relation(fields: [userId], references: [id], onDelete: Cascade)
  planId         String
  plan           NxCloudPlan   @relation(fields: [planId], references: [id])
  // The VM that runs this instance. onDelete:SetNull so tearing the VM down (a
  // customer terminate enqueues a Server DELETE) leaves a tombstone row rather
  // than orphaning the FK; the instance is normally deleted in the same action.
  serverId       String?       @unique
  server         Server?       @relation(fields: [serverId], references: [id], onDelete: SetNull)
  // Access surface. subdomain is the label under the NxCloud zone
  // (<subdomain>.nxcloud.nxeon.cloud); customDomain is a later phase.
  subdomain      String        @unique
  customDomain   String?       @unique
  sslActive      Boolean       @default(false)
  status         NxCloudStatus @default(PENDING)
  // Nextcloud admin bootstrap creds. The password is generated per instance,
  // stored ENCRYPTED, revealed to the customer ONCE then cleared — the same
  // discipline as HostingAccount.sftpPasswordEnc. An impersonating admin can
  // never exfiltrate it (assertNotImpersonating guards the reveal action).
  adminUser      String        @default("admin")
  adminPassEnc   String?
  // Usage meter, refreshed by a sweep (deferred for MVP; nullable until measured).
  storageUsedMB  Int?
  storageQuotaMB Int
  usageAt        DateTime?
  version        String? // installed Nextcloud version, once verified serving
  error          String? // last provisioning/serving issue (COMPLETED_WITH_ISSUES)
  provisionedAt  DateTime?
  createdAt      DateTime      @default(now())
  updatedAt      DateTime      @updatedAt
  tasks          NxCloudTask[]

  @@index([userId])
  @@index([status])
}

enum NxCloudTaskKind {
