"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser, assertNotImpersonating } from "./auth";
import { getSettingInt } from "./settings";
import { addMonths } from "./billing-terms";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { emailVerificationError } from "./email-verification";

// Block storage volumes: add-on disks a customer can order, then attach to /
// detach from one of their running servers. A volume is billed per GB / month.
// The physical Proxmox disk only exists once a volume has been attached at least
// once; `Volume.diskName` tracks where that disk currently lives on the VM
// (`scsiN` while attached, `unusedN` while detached) and `Volume.serverId` the
// VM that physically holds it. See worker/volumes.ts for the Proxmox side.

const MIN_GB = 1;
const MAX_GB = 2000;

/**
 * Price (in cents) for a volume of `sizeGB`, per-GB/month from Settings.
 *
 * PRIVATE. Every export of a `"use server"` file is a public network endpoint,
 * and this one had a single caller — `orderVolume`, twelve lines below — yet was
 * reachable by anyone, signed in or not, with no auth check of any kind. Nothing
 * imported it; it was exported only because it happened to be written next to
 * the actions. That is precisely how `verifyTotpForUser` became an
 * unauthenticated 2FA oracle: a helper that was never meant to be an endpoint
 * became one by living in the wrong file with the wrong keyword in front of it.
 */
async function volumePriceCents(sizeGB: number): Promise<number> {
  const perGb = await getSettingInt("volume_price_cents_per_gb", 10);
  return Math.max(0, Math.round(sizeGB)) * perGb;
}

async function ownedVolume(volumeId: string) {
  const user = await requireUser();
  const volume = await db.volume.findUnique({ where: { id: volumeId } });
  if (!volume) throw new Error("Not found");
  if (volume.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, volume };
}

async function ownedServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

/** Reject if the server already has a job queued or running (one in-flight per server). */
async function serverBusy(serverId: string): Promise<boolean> {
  const pending = await db.job.count({
    where: { serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  return pending > 0;
}

/**
 * Order a new block storage volume: debit the wallet up-front (one month) and
 * create the Volume row PENDING plus a VOLUME_CREATE job. The job flips it to
 * DETACHED (available to attach). No physical disk is created until attach.
 */
export async function orderVolume(
  name: string,
  sizeGB: number
): Promise<{ error?: string; id?: string }> {
  // Spend path: this debits the wallet up front, so it takes the same guard as
  // every other purchase (lib/actions.ts payAndDeploy, lib/actions-disk.ts
  // expandServerDisk, the domain transfer actions). It was the only wallet debit
  // in the storage product without one.
  await assertNotImpersonating();
  const user = await requireUser();
  // Purchase gate: an unverified address means we cannot reach the person we
  // are about to charge. See lib/email-verification.ts.
  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  const clean = (name ?? "")
    .replace(/[\x00-\x1f\x7f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length < 2 || clean.length > 40) {
    return { error: "Name must be 2–40 characters." };
  }
  const size = Math.round(Number(sizeGB));
  if (!Number.isFinite(size) || size < MIN_GB || size > MAX_GB) {
    return { error: `Size must be between ${MIN_GB} and ${MAX_GB} GB.` };
  }

  const priceCents = await volumePriceCents(size);

  let volumeId: string;
  try {
    volumeId = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, priceCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -priceCents,
          description: `Block storage volume: ${clean} (${size} GB)`,
        },
      });
      const v = await tx.volume.create({
        data: {
          userId: user.id,
          name: clean,
          sizeGB: size,
          priceCents,
          status: "PENDING",
          expiresAt: addMonths(new Date(), 1),
        },
      });
      await tx.job.create({ data: { type: "VOLUME_CREATE", payload: { volumeId: v.id } } });
      return v.id;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance — top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: { userId: user.id, action: "volume.order", detail: `${volumeId} ${clean} ${size}GB` },
  });
  revalidatePath("/dashboard/volumes");
  return { id: volumeId };
}

/** Attach a DETACHED volume to one of the caller's RUNNING servers. */
export async function attachVolume(
  volumeId: string,
  serverId: string
): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  const { server } = await ownedServer(serverId);

  if (volume.status !== "DETACHED") {
    return { error: "Only an available (detached) volume can be attached." };
  }
  if (!server.vmid || server.status !== "RUNNING") {
    return { error: "Target server must be running." };
  }
  // A volume that already holds data physically lives on one server's VM; it can
  // only be re-attached there (cross-node disk migration is out of scope).
  if (volume.serverId && volume.serverId !== serverId) {
    return { error: "This volume holds data on another server. Attach it there, or delete it first." };
  }
  if (await serverBusy(serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }

  // Claim the volume with a compare-and-swap on the state we just read, then
  // enqueue in the SAME transaction.
  //
  // The status check above is a snapshot. Two overlapping attach requests — a
  // double-click, or the same volume aimed at two different servers from two
  // tabs — both saw DETACHED, both wrote `serverId`, and both queued a
  // VOLUME_ATTACH. The row ended up pointing at one server while a job tried to
  // hot-plug the same disk onto another, and the second attach reports success
  // for work that cannot happen. The CAS makes exactly one of them win.
  const claimed = await db.volume.updateMany({
    where: {
      id: volumeId,
      status: "DETACHED",
      // Re-assert the "lives on one VM" rule inside the swap.
      OR: [{ serverId: null }, { serverId }],
    },
    data: { serverId },
  });
  if (claimed.count === 0) {
    return { error: "This volume was just claimed by another request — refresh the page to see where it is now." };
  }
  await db.job.create({ data: { type: "VOLUME_ATTACH", serverId, payload: { volumeId } } });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.attach", detail: `${volumeId} -> ${serverId}` },
  });
  revalidatePath("/dashboard/volumes");
  revalidatePath(`/dashboard/servers/${serverId}`);
  return {};
}

/** Detach an ATTACHED volume from its server (data is preserved as an unused disk). */
export async function detachVolume(volumeId: string): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  if (volume.status !== "ATTACHED" || !volume.serverId) {
    return { error: "Volume is not attached." };
  }
  if (await serverBusy(volume.serverId)) {
    return { error: "Another operation is already in progress on this server." };
  }
  await db.job.create({
    data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId } },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.detach", detail: `${volumeId}` },
  });
  revalidatePath("/dashboard/volumes");
  revalidatePath(`/dashboard/servers/${volume.serverId}`);
  return {};
}

/** Permanently delete a volume: detaches + destroys the disk, then removes the row. */
export async function deleteVolume(volumeId: string): Promise<{ error?: string }> {
  const { user, volume } = await ownedVolume(volumeId);
  if (volume.status === "DELETING") return { error: "Volume is already being deleted." };

  // If the disk physically lives on a server, route the delete through it and
  // honour the one-in-flight-job guard so we don't collide with another op.
  if (volume.serverId) {
    if (await serverBusy(volume.serverId)) {
      return { error: "Another operation is already in progress on this server." };
    }
  }
  // Same compare-and-swap as attach, for the same reason and with worse stakes:
  // this destroys a disk. Two overlapping deletes both read a non-DELETING row
  // and both queued a VOLUME_DELETE for it.
  const claimed = await db.volume.updateMany({
    where: { id: volumeId, status: { not: "DELETING" } },
    data: { status: "DELETING" },
  });
  if (claimed.count === 0) return { error: "Volume is already being deleted." };
  await db.job.create({
    data: {
      type: "VOLUME_DELETE",
      serverId: volume.serverId ?? undefined,
      payload: { volumeId },
    },
  });
  await db.auditLog.create({
    data: { userId: user.id, action: "volume.delete", detail: `${volumeId}` },
  });
  revalidatePath("/dashboard/volumes");
  if (volume.serverId) revalidatePath(`/dashboard/servers/${volume.serverId}`);
  return {};
}

