  const [templateKey, setTemplateKey] = useState(templates[0]?.key ?? "");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  function onCreate() {
    setError(null);
    start(async () => {
      const res = await createSite(name.trim() || "My site", templateKey);
      if (!res.ok) {
        setError(res.error);
        return;
      }
      router.push(`/dashboard/sites/${res.id}`);
    });
  }

  function onPublish(id: string) {
    setError(null);
    start(async () => {
      const res = await publishSite(id);
      if (!res.ok) setError(res.error);
      router.refresh();
    });
  }

  function onUnpublish(id: string) {
    setError(null);
    start(async () => {
      const res = await unpublishSite(id);
      if (!res.ok) setError(res.error);
      router.refresh();
    });
  }

  function onDelete(id: string) {
    setError(null);
    if (!confirm("Delete this site permanently? This cannot be undone.")) return;
