        <h2 className="mb-4 text-sm font-semibold text-slate-200">Create a new site</h2>
        <div className="mb-4 grid gap-3 sm:grid-cols-3">
          {templates.map((t) => (
            <button
              key={t.key}
              type="button"
              onClick={() => setTemplateKey(t.key)}
              className={`rounded-xl border p-4 text-left transition ${
                templateKey === t.key
                  ? "border-brand-500 bg-brand-500/10"
                  : "border-white/10 bg-white/[0.03] hover:border-white/20"
              }`}
            >
              <div className="mb-2 h-2 w-10 rounded-full" style={{ background: t.accent }} />
              <div className="text-sm font-semibold">{t.name}</div>
              <div className="mt-1 text-xs text-slate-400">{t.description}</div>
            </button>
          ))}
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="Site name (e.g. My Cafe)"
            maxLength={80}
            className="min-w-[220px] flex-1 rounded-lg border border-white/10 bg-navy-950/60 px-3 py-2 text-sm outline-none focus:border-brand-500"
          />
          <button
            type="button"
            onClick={onCreate}
            disabled={pending}
            className="rounded-lg bg-brand-500 px-5 py-2 text-sm font-semibold text-white disabled:opacity-50"
          >
            {pending ? "Working…" : "Create site"}
          </button>
        </div>
      </div>

      {/* Existing sites */}
      {sites.length === 0 ? (
        <EmptyState
          title="No sites yet"
          sub="Choose a template above to start building your first website."
        />
      ) : (
        <div className="space-y-3">
          {sites.map((s) => {
            const domain = `${s.slug}.${baseDomain}`;
            const live = s.status === "PUBLISHED";
            const busy = s.status === "PUBLISHING";
            return (
              <div key={s.id} className="card flex flex-wrap items-center justify-between gap-4 p-4">
                <div className="min-w-0">
