/**
 * Create a new site from a starter template: the Site row (DRAFT), its home
 * SitePage, and a draft SiteVersion holding the template's document.
 */
export async function createSite(name: string, templateKey?: string): Promise<CreateResult> {
  try {
    const user = await requireUser();
    const limited = throttle(user.id, "create", 10);
    if (limited) return { ok: false, error: limited };

    const cleanName = String(name ?? "").trim().slice(0, 80) || "My site";
    const tpl = getTemplate(templateKey) ?? getTemplate(DEFAULT_TEMPLATE_KEY)!;

    const count = await db.site.count({ where: { userId: user.id } });
    if (count >= 25) return { ok: false, error: "Site limit reached (25 per account)." };

    const slug = await uniqueSlug(cleanName);

    const site = await db.site.create({
      data: {
        userId: user.id,
        name: cleanName,
        slug,
        status: "DRAFT",
        templateKey: tpl.key,
        pages: {
          create: (tpl.document.pages ?? []).map((p, idx) => ({
            path: p.path,
            title: p.title ?? "",
            seoDesc: p.seoDesc ?? null,
            sortOrder: idx,
          })),
        },
        versions: {
          create: { document: tpl.document as unknown as object, isDraft: true, label: "Initial draft" },
        },
      },
    });
    await db.auditLog.create({
      data: { userId: user.id, action: "site.create", detail: `${cleanName} (${slug})` },
    });
    revalidatePath("/dashboard/sites");
    return { ok: true, id: site.id };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/** Load a site plus its current draft document, for the editor. */
export async function getSiteForEdit(id: string): Promise<
  | { ok: true; site: SiteRow; document: SiteDocument | null }
