/**
 * Persist the editor's working document as the site's draft. The client-supplied
 * document is validated with `isSiteDocument` before it is stored — never trust
 * the shape of anything that came over the wire.
 */
export async function saveDraft(id: string, document: unknown): Promise<Result> {
  try {
    const { user, site } = await ownedSite(id);
    const limited = throttle(user.id, "save", 60);
    if (limited) return { ok: false, error: limited };
    if (!isSiteDocument(document)) {
      return { ok: false, error: "The editor document is malformed and was not saved." };
    }
    // Cap the stored payload so a runaway document can't wedge the DB / publish.
    const size = JSON.stringify(document).length;
    if (size > 5_000_000) {
      return { ok: false, error: "This page is too large to save. Try removing some large embedded images." };
    }

    const existing = await db.siteVersion.findFirst({
      where: { siteId: site.id, isDraft: true },
      orderBy: { createdAt: "desc" },
    });
    if (existing) {
      await db.siteVersion.update({
        where: { id: existing.id },
        data: { document: document as unknown as object },
      });
    } else {
      await db.siteVersion.create({
        data: { siteId: site.id, document: document as unknown as object, isDraft: true },
      });
    }
    await db.site.update({ where: { id: site.id }, data: { updatedAt: new Date() } });
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

export async function renameSite(id: string, name: string): Promise<Result> {
  try {
    const { user, site } = await ownedSite(id);
    const limited = throttle(user.id, "rename", 20);
    if (limited) return { ok: false, error: limited };
    const cleanName = String(name ?? "").trim().slice(0, 80);
    if (!cleanName) return { ok: false, error: "Enter a name." };
    // The slug is the live subdomain and is intentionally NOT changed by a
    // rename — renaming a published site must not move its URL out from under it.
    await db.site.update({ where: { id: site.id }, data: { name: cleanName } });
    revalidatePath("/dashboard/sites");
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/**
 * Publish the current draft: flip the Site to PUBLISHING and enqueue a
 * SITE_PUBLISH job. The worker renders the bundle and writes it atomically into
 * `/var/www/<slug>.<base>`; only the worker may set PUBLISHED, and only on proof.
 */
export async function publishSite(id: string): Promise<Result> {
  try {
    const { user, site } = await ownedSite(id);
    const limited = throttle(user.id, "publish", 12);
    if (limited) return { ok: false, error: limited };
    if (site.status === "PUBLISHING") {
      return { ok: false, error: "This site is already publishing — give it a moment." };
    }
    const draft = await db.siteVersion.findFirst({
      where: { siteId: site.id, isDraft: true },
      orderBy: { createdAt: "desc" },
    });
    if (!draft || !isSiteDocument(draft.document)) {
      return { ok: false, error: "There is nothing to publish yet — save your site first." };
    }
    await db.site.update({ where: { id: site.id }, data: { status: "PUBLISHING", error: null } });
    await db.job.create({ data: { type: "SITE_PUBLISH", payload: { siteId: site.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "site.publish", detail: `${site.name} (${site.slug})` },
    });
    revalidatePath("/dashboard/sites");
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

/** Take a published site offline: enqueue a SITE_UNPUBLISH job. */
export async function unpublishSite(id: string): Promise<Result> {
  try {
    const { user, site } = await ownedSite(id);
    const limited = throttle(user.id, "unpublish", 12);
    if (limited) return { ok: false, error: limited };
    if (site.status !== "PUBLISHED" && site.status !== "FAILED") {
      return { ok: false, error: "This site is not published." };
    }
    await db.site.update({ where: { id: site.id }, data: { status: "PUBLISHING", error: null } });
    await db.job.create({ data: { type: "SITE_UNPUBLISH", payload: { siteId: site.id } } });
    await db.auditLog.create({
      data: { userId: user.id, action: "site.unpublish", detail: `${site.name} (${site.slug})` },
    });
    revalidatePath("/dashboard/sites");
    return { ok: true };
  } catch (err) {
    return { ok: false, error: safeError(err) };
  }
}

