 *
 * APPROVAL. The customer chooses how Claude may act before connecting:
 *   - "auto"  — auto-approve everything (Claude runs commands + edits files on
 *               its own; fastest, least safe).
 *   - "ask"   — ask before changes; the backend forwards each change request as a
 *               permission frame the customer approves/denies inline here.
 * The chosen mode is sent to the backend as `&approval=auto|ask`.
 */

type ChatItem =
  | { id: number; role: "user"; text: string }
  | { id: number; role: "assistant"; text: string }
  | {
      id: number;
      role: "tool";
      toolId: string;
      name: string;
      summary: string;
      status: "running" | "done" | "error";
      result: string;
    }
  | {
      id: number;
      role: "permission";
      reqId: string;
      tool: string;
      summary: string;
      status: "pending" | "approved" | "denied";
