/** Local-time first/last day of the current month grid (6 weeks), so the
 *  initial fetch matches the Month view the client opens on. */
function initialRange(): [string, string] {
  const now = new Date();
  const firstOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const gridStart = new Date(firstOfMonth);
  gridStart.setDate(gridStart.getDate() - gridStart.getDay());
  const gridEnd = new Date(gridStart);
  gridEnd.setDate(gridEnd.getDate() + 42);
  return [gridStart.toISOString(), gridEnd.toISOString()];
}

export default async function CalendarPage() {
  await requireUser();

  let calendars: CalendarInfo[] = [];
  let events: CalEvent[] = [];
  let tasks: TaskItem[] = [];
  let failed = false;

  try {
    calendars = await listCalendars();
    if (calendars.length > 0) {
      const [start, end] = initialRange();
      [events, tasks] = await Promise.all([listEvents(start, end), listTasks()]);
    }
  } catch {
    failed = true;
  }

  // An outage and an empty account are OPPOSITE situations and must not share a
  // screen: telling a paying mailbox owner whose CalDAV server hiccuped that they
  // have "no calendar connected" — and pushing them to buy email they already own
  // — hides the fault and sends them the wrong way. mail/page.tsx already splits
  // these; this page used to fold both into the empty state.
  if (failed) {
    return (
      <div className="mx-auto max-w-2xl pt-10">
        <EmptyState
          title="Couldn't reach your calendar"
          sub="We couldn't load your calendar just now — this is usually a brief hiccup on the calendar server, not a problem with your account. Reload in a moment; if it keeps happening, open a support ticket and we'll look into it."
          action={
