  }

  if (calendars.length === 0) {
    return (
      <div className="mx-auto max-w-2xl pt-10">
        <EmptyState
          title="No calendar connected"
          sub="Your calendar lives alongside your Nxeon mailbox. Set up business email on one of your domains to start scheduling events and tracking tasks here."
          action={
            <Link href="/dashboard/email" className="btn-primary">
              Set up email
            </Link>
          }
        />
      </div>
    );
  }

  return (
    <>
      <PortalHero variant="calendar" title="Calendar" sub="Your schedule, events, and tasks." />
      <CalendarClient initialCalendars={calendars} initialEvents={events} initialTasks={tasks} />
    </>
