import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { AutoRefresh } from "@/components/AutoRefresh";
import { PortalHero } from "@/components/portal/PortalHero";
import {
  SslCertificates,
  type CertRow,
  type QueueInfo,
  type ServerOption,
} from "@/components/customer/SslCertificates";

export const dynamic = "force-dynamic";

type SslPayload = { certId?: string; domain?: string; renewal?: boolean };

export default async function SslPage() {
  const user = await requireUser();

  const [certificates, servers] = await Promise.all([
    db.sslCertificate.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
    db.server.findMany({
      where: { userId: user.id },
      orderBy: { createdAt: "desc" },
    }),
  ]);

  const serverName = new Map(servers.map((s) => [s.id, s.hostname]));
  const myServerIds = new Set(servers.map((s) => s.id));

  // ---------------------------------------------------------------------------
  // Queue visibility.
  //
  // The worker claims ONE job at a time platform-wide — `worker/index.ts` picks
  // the oldest `status: "QUEUED"` row and awaits it inside a serial `for(;;)` —
  // so a certificate request genuinely can sit behind another tenant's long
  // MIGRATE. That happened on 2026-07-26: a request read "pending" for 13
  // minutes with nothing on screen to distinguish a queue from a crash, so the
  // customer had no way to know whether to wait or retry. Resolve the real
  // position here (this page already polls) instead of leaving them guessing.
  // ---------------------------------------------------------------------------
  const inflight = certificates.filter((c) => c.status === "PENDING" || c.status === "ISSUING");
  const queueByCert = new Map<string, QueueInfo>();

  if (inflight.length > 0) {
    const [sslJobs, running] = await Promise.all([
      db.job.findMany({
        where: { type: "SSL_ISSUE", status: { in: ["QUEUED", "RUNNING"] } },
        select: { id: true, status: true, createdAt: true, payload: true },
        orderBy: { createdAt: "asc" },
      }),
      // Whatever is holding the single worker slot right now.
      db.job.findFirst({
        where: { status: "RUNNING" },
        select: { type: true, serverId: true },
        orderBy: { createdAt: "asc" },
      }),
    ]);

    for (const cert of inflight) {
      const job = sslJobs.find((j) => ((j.payload ?? {}) as SslPayload).certId === cert.id);

      // No queued or running job at all: the request cannot make progress. Say so
      // rather than spinning — the reconcile sweep will age it out, and the row is
      // deletable in the meantime.
      if (!job) {
        queueByCert.set(cert.id, {
          state: "none",
          position: 0,
          aheadCount: 0,
          queuedAtIso: cert.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      if (job.status === "RUNNING") {
        queueByCert.set(cert.id, {
          state: "running",
          position: 0,
          aheadCount: 0,
          queuedAtIso: job.createdAt.toISOString(),
          blocking: null,
        });
        continue;
      }

      // FIFO by createdAt, matching the worker's claim order exactly.
      const aheadCount = await db.job.count({
        where: { status: "QUEUED", createdAt: { lt: job.createdAt } },
      });
      queueByCert.set(cert.id, {
        state: "queued",
        position: aheadCount + 1,
        aheadCount,
        queuedAtIso: job.createdAt.toISOString(),
        blocking: running
          ? {
              type: running.type,
              // Only the job type is exposed, never whose server it is beyond
              // "yours or not" — enough to explain the wait, nothing more.
              mine: running.serverId ? myServerIds.has(running.serverId) : false,
            }
          : null,
      });
    }
  }

  const rows: CertRow[] = certificates.map((c) => ({
    id: c.id,
    domain: c.domain,
    status: c.status,
    issuer: c.issuer,
    autoRenew: c.autoRenew,
    serverName: c.serverId ? serverName.get(c.serverId) ?? null : null,
    issuedAt: c.issuedAt ? c.issuedAt.toISOString() : null,
    // The observed notAfter, or null. Nothing here is ever a computed guess.
    expiresAt: c.expiresAt ? c.expiresAt.toISOString() : null,
    lastError: c.lastError,
    queue: queueByCert.get(c.id) ?? null,
  }));

  // Certificate issuance needs a live, DNS-pointed server, so only offer running ones.
  const serverOptions: ServerOption[] = servers
    .filter((s) => s.status === "RUNNING")
    .map((s) => ({ id: s.id, hostname: s.hostname }));

  const transitional = inflight.length > 0;

  return (
    <div className="space-y-6">
      {transitional && <AutoRefresh />}
      <PortalHero
        variant="ssl"
        title="SSL Certificates"
        sub="One-click Let's Encrypt certificates for domains pointed at your servers. Renewed automatically from 21 days before expiry."
      />
      <SslCertificates certificates={rows} servers={serverOptions} />
    </div>
  );
}

