export type SiteServingView = { domain: string; serving: boolean; code: string };
export type RemediationResult = {
  error?: string;
  ok?: boolean;
  /** Domains that serve their real site now. */
  serving?: string[];
  /** Domains that still do not serve. */
  dark?: string[];
  /** Did the whole migration flip to fully-served (status → DONE)? */
  allServing?: boolean;
  /** Short human lines describing what the finish step did. */
  log?: string[];
};

async function ownedMigrationForRemediation(id: string) {
  const user = await requireUser();
  const m = await db.migration.findUnique({ where: { id } });
  if (!m) return { error: "That migration no longer exists." as const };
  if (m.userId !== user.id && user.role !== "ADMIN") return { error: "Not your migration." as const };
  const server = await db.server.findUnique({
    where: { id: m.serverId },
    select: {
      id: true,
      hostname: true,
      rootPassword: true,
      rootPasswordEnc: true,
      sshPort: true,
      dedicatedIp: { select: { address: true } },
    },
  });
  if (!server) return { error: "The target server for this migration is gone." as const };
  return { user, m, server };
}

/** The domains to re-check: what the source served, from the stored scan. */
function migrationProbeDomains(items: unknown): string[] {
  const scan = ((items ?? {}) as { scan?: { vhostDomains?: unknown[] } }).scan ?? {};
  const out = new Set<string>();
  for (const d of scan.vhostDomains ?? []) {
    const h = cleanHostname(String(d ?? ""));
    if (h) out.add(h);
  }
  return [...out].slice(0, 30);
}

/**
 * Ask the TARGET (over its own loopback, so no DNS is needed) what it serves for
 * `domain`, and whether that is a real site or a placeholder. HTTPS is checked
 * first (authoritative when a cert exists), then HTTP.
 */
async function probeDomainOnTarget(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domain: string): Promise<SiteServingView> {
  if (!/^[a-z0-9.-]{1,253}$/.test(domain)) return { domain, serving: false, code: "000" };
  const httpsCode = (
    await exec(conn, `curl -sk -o /tmp/nxeon-probe -m 8 --resolve ${domain}:443:127.0.0.1 -w '%{http_code}' https://${domain}/ 2>/dev/null`, 15000)
  ).stdout.trim().slice(0, 3);
  let code = httpsCode;
  if (!/^[1-9]\d\d$/.test(code)) {
    code = (
      await exec(conn, `curl -s -o /tmp/nxeon-probe -m 8 -H 'Host: ${domain}' -w '%{http_code}' http://127.0.0.1/ 2>/dev/null`, 15000)
    ).stdout.trim().slice(0, 3);
  }
  const body = (await exec(conn, `head -c 4096 /tmp/nxeon-probe 2>/dev/null`, 10000)).stdout;
  const serving = /^(2|3)\d\d$/.test(code) && !PLACEHOLDER_RE.test(body);
  return { domain, serving, code: code || "000" };
}

async function reprobeAndSettle(conn: Parameters<Parameters<typeof withServerSsh>[1]>[0], domains: string[]): Promise<SiteServingView[]> {
  const results = new Map<string, SiteServingView>();
  for (const d of domains) results.set(d, await probeDomainOnTarget(conn, d));
  return [...results.values()];
}

async function persistServingOutcome(migrationId: string, currentStatus: string, probes: SiteServingView[]): Promise<boolean> {
  const dark = probes.filter((p) => !p.serving);
  const allServing = probes.length > 0 && dark.length === 0;
  // Only ever UPGRADE the honest verdict — a re-check that finds everything live
  // flips COMPLETED_WITH_ISSUES → DONE. Never downgrade (that belongs to the
  // engine's own run, not a spot re-check).
  if (allServing && currentStatus === "COMPLETED_WITH_ISSUES") {
    await db.migration.update({
      where: { id: migrationId },
      data: { status: "DONE", step: "Completed — all sites serving" },
    }).catch(() => {});
  }
  return allServing;
}

/**
 * Re-check (only) whether each site serves now, and flip the migration to DONE
 * if they all do. No bring-up — just an honest re-probe. Cheap; safe to spam.
 */
export async function recheckMigrationServing(migrationId: string): Promise<RemediationResult> {
  const ctx = await ownedMigrationForRemediation(migrationId);
  if ("error" in ctx) return { error: ctx.error };
  const { m, server, user } = ctx;
  const rl = checkRateLimit(`migrate:recheck:${user.id}`, { max: 20, windowMs: 5 * 60 * 1000 });
  if (!rl.ok) return { error: `Please wait ${rl.retryAfterSec}s before checking again.` };
  const domains = migrationProbeDomains(m.items);
  if (!domains.length) return { ok: true, serving: [], dark: [], allServing: false, log: ["No domains to check."] };
  if (SANDBOX) {
    return { ok: true, serving: domains, dark: [], allServing: true, log: ["Sandbox: pretended all sites serve."] };
  }
  try {
    const probes = await withServerSsh(server, (conn) => reprobeAndSettle(conn, domains));
    const allServing = await persistServingOutcome(m.id, m.status, probes);
    revalidatePath("/dashboard/migrate");
    return {
      ok: true,
      serving: probes.filter((p) => p.serving).map((p) => p.domain),
      dark: probes.filter((p) => !p.serving).map((p) => p.domain),
      allServing,
    };
  } catch {
    return { error: "Couldn't reach the new server to check. Try again in a moment." };
  }
}

