 *     missing, queue ENSURE_DBMGR, report { provisioning:true }
 * Owner-or-admin + not-impersonating (this mints a live DB credential on the box).
 * SANDBOX: mark ready immediately (no real node).
 */
export async function ensureDbManager(accountId: string): Promise<DbMgrStatus & { error?: string }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
  await assertNotImpersonating();
  const { a } = ctx;
  if (!isValidUnixUsername(a.username)) return { ready: false, provisioning: false, enabled: false, error: "Account not ready." };

  if (SANDBOX) {
    if (!a.dbMgrReady) {
      await db.hostingAccount.update({
        where: { id: a.id },
        data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: true },
      });
    }
    return { ready: true, provisioning: false, enabled: true };
  }

  if (a.dbMgrReady && a.dbMgrUser && a.dbMgrPassEnc) return { ready: true, provisioning: false, enabled: true };

  // Generate + persist the manager credential once (encrypted at rest); the
  // worker applies it on the node. Keep the same password across re-queues so the
  // stored cred always matches what the node was told.
  if (!a.dbMgrUser || !a.dbMgrPassEnc) {
    await db.hostingAccount.update({
      where: { id: a.id },
      data: { dbMgrUser: dbMgrUserFor(a.username), dbMgrPassEnc: encryptSecret(newSecret()), dbMgrReady: false },
    });
  }
  const inFlight = await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } });
  if (!inFlight) await db.hostingTask.create({ data: { accountId, kind: "ENSURE_DBMGR" } });
  revalidatePath(`/dashboard/hosting/${accountId}`);
  return { ready: false, provisioning: true, enabled: true };
}

export async function dbmgrStatus(accountId: string): Promise<DbMgrStatus & { error?: string }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { ready: false, provisioning: false, enabled: false, error: ctx.error };
  const { a } = ctx;
  if (SANDBOX) return { ready: !!a.dbMgrReady, provisioning: false, enabled: true };
  const provisioning = !a.dbMgrReady && !!(await db.hostingTask.findFirst({ where: { accountId, kind: "ENSURE_DBMGR", status: { in: ["PENDING", "RUNNING"] } } }));
  return { ready: !!a.dbMgrReady, provisioning, enabled: true };
}

/** The account's databases — read straight from OUR portal tables (never the
 *  node), so this leaks nothing and needs no MySQL round-trip. Owner-or-admin. */
export async function dbmgrListDatabases(accountId: string): Promise<{ error?: string; databases?: DbMgrDatabase[] }> {
  const ctx = await loadOwned(accountId);
  if ("error" in ctx) return { error: ctx.error };
  const rows = await db.hostingDatabase.findMany({ where: { accountId, status: { in: ["ACTIVE", "PENDING"] } }, orderBy: { createdAt: "asc" } });
  return { databases: rows.map((r) => ({ name: r.name, status: r.status })) };
}

"use client";

import { useEffect, useState } from "react";
import { createHostingBackup, listHostingBackups, restoreHostingBackup } from "@/lib/actions-hosting";

/** Backup list + create/restore for a hosting account. Extracted verbatim from
 *  the old HostingClient; behaviour is identical. */
export function Backups({ accountId }: { accountId: string }) {
  const [backups, setBackups] = useState<{ id: string; sizeBytes: number; createdAt: string }[]>([]);
  const [busy, setBusy] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const load = () => listHostingBackups(accountId).then((b) => { setBackups(b); setLoaded(true); }).catch(() => setLoaded(true));
  useEffect(() => { load(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [accountId]);
  const mb = (b: number) => (b / 1024 / 1024).toFixed(1) + " MB";
  return (
    <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
      <div className="flex items-center justify-between">
        <p className="text-sm font-medium text-slate-300">Backups <span className="text-xs text-slate-500">({backups.length})</span></p>
        <button
          className="btn-secondary text-xs"
          disabled={busy}
          onClick={async () => { setBusy(true); const r = await createHostingBackup(accountId); if (r.error) alert(r.error); setBusy(false); setTimeout(load, 1500); }}
        >
          {busy ? "…" : "Back up now"}
        </button>
      </div>
      {loaded && backups.length === 0 && (
        <p className="mt-1.5 text-xs text-slate-500">No backups yet. Run one before big changes — we keep the latest 5.</p>
      )}
      {backups.length > 0 && (
        <ul className="mt-2 space-y-0.5 text-xs">
          {backups.map((b) => (
            <li key={b.id} className="flex items-center justify-between text-slate-400">
              <span>{new Date(b.createdAt).toLocaleString()} · {mb(b.sizeBytes)}</span>
              <button
                className="text-brand-300 hover:underline"
                onClick={async () => { if (confirm("Restore this backup? It overwrites current files and databases.")) { const r = await restoreHostingBackup(accountId, b.id); if (r.error) alert(r.error); } }}
              >
                Restore
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
